  /** The annotated text verbatim (non-blank). */
  quote: string;
  /** The markdown section's stable id (required for markdown annotations, forbidden otherwise). */
  sectionId?: string | null | undefined;
  /** The range's first character offset within the anchor text (inclusive, ≥ 0). */
